from PIL import Image
def bore(f):
    a=Image.open(f).convert('L'); W,H=a.size; p=a.load()
    # dark pixels below gripper, cluster nearest center-x 320
    pts=[(x,y) for y in range(312,H) for x in range(W) if p[x,y]<60]
    # connected comps simple: group by x<450
    pts=[q for q in pts if q[0]<460]
    xs=[x for x,y in pts]; ys=[y for x,y in pts]
    return sum(xs)/len(xs),sum(ys)/len(ys),len(pts),min(xs),max(xs),min(ys),max(ys)
def pin(f):
    b=Image.open(f).convert('RGB'); q=b.load(); W,H=b.size
    pts=[(x,y) for y in range(312,H) for x in range(0,560) if min(q[x,y])>225]
    xs=[x for x,y in pts]; ys=[y for x,y in pts]
    return sum(xs)/len(xs),sum(ys)/len(ys),len(pts),min(xs),max(xs),min(ys),max(ys)
for f in ['wrist_005.png','wrist_008.png']: print(f,bore(f))
for f in ['wrist_004.png','wrist_009.png','wrist_010.png']: print(f,pin(f))
